INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Datenschutz-Folgenabschätzung (DSFA) immer Pflicht?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei hohem Risiko nötig"}, {"text": "Ja", "correct": false, "because": "Abhängig von Verarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer DSFA?', 3, '[{"text": "Risikobewertung", "correct": true, "because": "Identifiziert Datenschutzrisiken"}, {"text": "Performance-Steigerung", "correct": false, "because": "Nicht primär relevant"}, {"text": "Kostensenkung", "correct": false, "because": "Sicherheit steht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer DSFA?', 5, '[{"text": "Beschreibung der Verarbeitung", "correct": true, "because": "Zeigt, was analysiert wird"}, {"text": "Risikoeinschätzung", "correct": true, "because": "Bewertet Gefahren"}, {"text": "Farbschema", "correct": false, "because": "Nicht datenschutzrelevant"}, {"text": "UI-Design", "correct": false, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine DSFA ist bei neuen Projekten nötig. b) Sie ist nur für große Firmen Pflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Größe ist egal, Risiko zählt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer DSFA?', 4, '[{"text": "Betroffenenrechte", "correct": false, "because": "Müssen berücksichtigt werden"}, {"text": "Risikomaßnahmen", "correct": false, "because": "Teil der Abschätzung"}, {"text": "Typografie", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine DSFA auch technische Maßnahmen bewertet?', 2, '[{"text": "Ja", "correct": true, "because": "Schutzmaßnahmen werden geprüft"}, {"text": "Nein", "correct": false, "because": "Technik ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wann ist eine DSFA laut DSGVO erforderlich?', 3, '[{"text": "Bei hohem Risiko für Betroffene", "correct": true, "because": "Schützt Rechte"}, {"text": "Bei jeder Datenverarbeitung", "correct": false, "because": "Nur bei Risiko"}, {"text": "Nur bei kleinen Projekten", "correct": false, "because": "Risikoabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zu einer DSFA?', 5, '[{"text": "Risiken identifizieren", "correct": true, "because": "Kern der Bewertung"}, {"text": "Maßnahmen planen", "correct": true, "because": "Reduziert Risiken"}, {"text": "Datenbankdesign", "correct": false, "because": "Nicht primär"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Datenschutzfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine DSFA schützt vor Datenschutzverletzungen. b) Sie ist nur ein Formular. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sie ist ein Prozess, kein Formular"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine DSFA?', 4, '[{"text": "Datenflussanalyse", "correct": false, "because": "Zeigt Verarbeitung"}, {"text": "Risikobewertung", "correct": false, "because": "Kern der DSFA"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine DSFA nur für sensible Daten nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Risiko entscheidet, nicht Datenart"}, {"text": "Ja", "correct": false, "because": "Umfang ist risikobasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bewertet eine DSFA?', 4, '[{"text": "Risiken für Betroffene", "correct": true, "because": "Fokus auf Rechte"}, {"text": "Technische Schutzmaßnahmen", "correct": true, "because": "Reduziert Gefahren"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine DSFA nur einmal nötig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen erfordern Updates"}, {"text": "Ja", "correct": false, "because": "Regelmäßige Prüfung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer DSFA?', 3, '[{"text": "Risiken für Betroffene", "correct": true, "because": "Schutz steht im Vordergrund"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Gründlichkeit zählt"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine DSFA ist bei hohem Risiko Pflicht. b) Sie ersetzt technische Maßnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Maßnahmen sind ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte prüfe ich in einer DSFA?', 5, '[{"text": "Datenarten", "correct": true, "because": "Beeinflusst Risiko"}, {"text": "Verarbeitungszwecke", "correct": true, "because": "Definiert Umfang"}, {"text": "UI-Design", "correct": false, "because": "Nicht datenschutzrelevant"}, {"text": "Servergeschwindigkeit", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer DSFA unwichtig?', 3, '[{"text": "Betroffenenrechte", "correct": false, "because": "Kern der Analyse"}, {"text": "Risikomanagement", "correct": false, "because": "Hauptziel"}, {"text": "Schriftgrößen", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der DSFA? Ist sie nur für neue Projekte?', 3, '[{"text": "Nein", "correct": true, "because": "Auch bei Änderungen nötig"}, {"text": "Ja", "correct": false, "because": "Risikoabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine DSFA rechtliche Folgen hat?', 2, '[{"text": "Ja", "correct": true, "because": "Pflichtverletzung kann Bußgelder bringen"}, {"text": "Nein", "correct": false, "because": "DSGVO verlangt sie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine DSFA?', 4, '[{"text": "Risikoanalyse", "correct": true, "because": "Bewertet Gefahren"}, {"text": "Statisches Mockup", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]');
